import Foundation

// Texts of the vehicle registration card and the card diagnostics, all languages in one table. Same texts as LocCards.cs
// (Windows, Linux) and the Android strings.xml files. Serbian Cyrillic is derived from the Latin text.

extension Loc {
    /// Looks up a key of this table (string keys, so the main `L` enum stays untouched).
    func x(_ key: String) -> String {
        guard let row = Self.cards[key] else { return key }
        if language == .srCyrl {
            if let c = Self.cardsCyrillic[key] { return c }
            let c = SerbianScript.cyrillic(row[.sr] ?? key)
            Self.cardsCyrillic[key] = c
            return c
        }
        return row[language] ?? row[.en] ?? key
    }

    private static var cardsCyrillic: [String: String] = [:]

    // swiftlint:disable line_length
    static let cards: [String: [AppLanguage: String]] = [
        "vehTitle": [.ru: "Саобраћајна дозвола", .en: "Vehicle registration card", .sr: "Saobraćajna dozvola", .hu: "Forgalmi engedély (chipkártya)", .sq: "Libreza e automjetit (karta me çip)", .sk: "Osvedčenie o evidencii vozidla (čipová karta)", .ro: "Card de înmatriculare a vehiculului", .hr: "Prometna dozvola (čip kartica)", .uk: "Свідоцтво про реєстрацію ТЗ (чип-картка)", .be: "Пасведчанне аб рэгістрацыі ТС (чып-карта)"],
        "vehNote": [.ru: "Разбор сделан по спецификации ЕС и МУП; на реальной карте ещё не проверен. Подпись издателя не проверяется.", .en: "Parsed according to the EU and MUP specifications; not yet verified on a real card. The issuer signature is not checked.", .sr: "Raščlanjeno prema specifikaciji EU i MUP-a; još nije proveren na pravoj kartici. Potpis izdavaoca se ne proverava.", .hu: "A szétbontás az EU és a MUP specifikációja szerint történt; valódi kártyán még nincs ellenőrizve. A kiállító aláírását nem ellenőrizzük.", .sq: "Të dhënat janë lexuar sipas specifikimeve të BE-së dhe MUP-it; ende nuk janë verifikuar në një kartë të vërtetë. Nënshkrimi i lëshuesit nuk kontrollohet.", .sk: "Údaje sú spracované podľa špecifikácií EÚ a MUP; zatiaľ neoverené na skutočnej karte. Podpis vydavateľa sa nekontroluje.", .ro: "Datele sunt interpretate conform specificațiilor UE și MUP; încă neverificate pe un card real. Semnătura emitentului nu este verificată.", .hr: "Podaci su obrađeni prema specifikacijama EU-a i MUP-a; još nisu provjereni na stvarnoj kartici. Potpis izdavatelja se ne provjerava.", .uk: "Дані розібрано за специфікаціями ЄС і МУП; на справжній картці ще не перевірено. Підпис видавця не перевіряється.", .be: "Даныя разабраны паводле спецыфікацый ЕС і МУП; на сапраўднай карце яшчэ не правераны. Подпіс выдаўца не правяраецца."],
        "cardUnknown": [.ru: "Карта не распознана: это не удостоверение личности и не саобраћајна дозвола (или имя приложения на её чипе нам ещё не известно). Запустите диагностику (скрытый пункт в Настройках: 5 нажатий на номер версии в «О программе») и пришлите журнал.", .en: "The card was not recognised: it is neither an ID card nor a vehicle registration card (or the application name on its chip is not known to us yet). Run the diagnostics (hidden item in Settings: tap the version number in About 5 times) and send the log.", .sr: "Kartica nije prepoznata: nije ni lična karta ni saobraćajna dozvola (ili nam naziv aplikacije na njenom čipu još nije poznat). Pokrenite dijagnostiku (skrivena stavka u Podešavanjima: 5 klikova na broj verzije u „O programu“) i pošaljite log.", .hu: "A kártya nem ismerhető fel: nem személyi igazolvány és nem forgalmi engedély (vagy a chipjén lévő alkalmazás neve még nem ismert). Futtassa a diagnosztikát (rejtett elem a Beállításokban: koppintson ötször a verziószámra a Névjegy oldalon), és küldje el a naplót.", .sq: "Karta nuk u njoh: nuk është as letërnjoftim, as librezë e automjetit (ose emri i aplikacionit në çipin e saj nuk na është ende i njohur). Ekzekutoni diagnostikimin (zëri i fshehur te Cilësimet: prekni 5 herë numrin e versionit te Rreth aplikacionit) dhe dërgoni regjistrin.", .sk: "Karta nebola rozpoznaná: nie je to ani občiansky preukaz, ani osvedčenie o evidencii vozidla (alebo názov aplikácie na jej čipe zatiaľ nepoznáme). Spustite diagnostiku (skrytá položka v Nastaveniach: ťuknite 5-krát na číslo verzie v časti O aplikácii) a pošlite záznam.", .ro: "Cardul nu a fost recunoscut: nu este nici carte de identitate, nici card de înmatriculare a vehiculului (sau numele aplicației de pe cip nu ne este încă cunoscut). Rulați diagnosticarea (element ascuns în Setări: atingeți de 5 ori numărul versiunii din Despre) și trimiteți jurnalul.", .hr: "Kartica nije prepoznata: nije ni osobna iskaznica ni prometna dozvola (ili nam naziv aplikacije na njezinu čipu još nije poznat). Pokrenite dijagnostiku (skrivena stavka u Postavkama: dodirnite 5 puta broj verzije u O aplikaciji) i pošaljite zapis.", .uk: "Картку не розпізнано: це не посвідчення особи і не свідоцтво про реєстрацію транспортного засобу (або назва програми на її чипі нам ще невідома). Запустіть діагностику (прихований пункт у Налаштуваннях: торкніться 5 разів номера версії в розділі «Про програму») і надішліть журнал.", .be: "Картку не распазнана: гэта не пасведчанне асобы і не пасведчанне аб рэгістрацыі транспартнага сродку (або назва праграмы на яе чыпе нам яшчэ невядомая). Запусціце дыягностыку (схаваны пункт у Наладах: націсніце 5 разоў на нумар версіі ў раздзеле «Пра праграму») і адпраўце журнал."],
